return $input.all().map((item, index) => {
  try {
    const rawText = item.json.content.parts[0].text;
    const cleanText = rawText.replace(/```json|```/g, "").trim();
    const cleanData = JSON.parse(cleanText);

    // Fallback logic to prevent "undefined"
    const source = $("Remove Duplicates").all()[index]?.json || {};

    return {
      json: {
        title: source.title || "Unknown Threat Title",
        link: source.link || "https://cysafepath.com",
        summary: cleanData.summary || "Summary currently being analyzed...",
        severity: cleanData.severity || 3,
        mitigation: cleanData.mitigation || "Consult internal security policy.",
        category: cleanData.category || "General Security"
      }
    };
  } catch (e) {
    return { json: { error: "Check AI Output Format", title: "Data Parsing Error" } };
  }
});

const blocks = [
  {
    type: "header",
    text: {
      type: "plain_text",
      text: "🚀 Daily Competitor & Market Report"
    }
  },
  { type: "divider" }
];

for (const item of $json.data || []) {
  blocks.push(
    {
      type: "section",
      text: {
        type: "mrkdwn",
        text: `*${item.title}*\n${item.summary}`
      },
      accessory: {
        type: "button",
        text: { type: "plain_text", text: "View Article" },
        url: item.link
      }
    },
    {
      type: "context",
      elements: [
        {
          type: "mrkdwn",
          text: `Category: ${item.category} | Importance: ${item.importance ?? "N/A"}/5`
        }
      ]
    },
    { type: "divider" }
  );
}

return [{ json: { blocks } }];

const rssData = {
  "CISA Gov": "https://www.cisa.gov/cybersecurity-advisories/all.xml",
  "HackerNews": "https://feeds.feedburner.com/TheHackersNews",
  "Bleeping Computer": "https://www.bleepingcomputer.com/feed/",
};

// Map the object into an array of items n8n can loop through
return Object.entries(rssData).map(([name, url]) => {
  return {
   name: name,
  url: url
  };
});
